constraints:
1 <= n <= 10^{5}
0 <= arr[i] <= 10^{9}

expected time complexity: O(n log n)
expected auxiliary space: O(n)

standard_solution_code:
from typing import List

class Solution:

	def smallerSum(self, n: int, arr: List[int]) -> List[int]:
		sorted_a = sorted(arr)
		smaller = {}
		prev_i = -1
		prev_a = 0
		summ = 0
		for (i, a) in enumerate(sorted_a):
			if a not in smaller:
				summ = summ + (i - prev_i) * prev_a
				smaller[a] = summ
				prev_a = a
				prev_i = i
		return [smaller[a] for a in arr]
